"""Data models for the ledger package.

Money is stored as integer minor units (cents) to avoid float rounding errors.
"""

from __future__ import annotations

from dataclasses import dataclass, field
from datetime import date, datetime, timezone


class LedgerError(Exception):
    """Base class for all ledger errors."""


class OverdraftError(LedgerError):
    """Raised when a transfer would drive an account below zero."""

    def __init__(self, account: str, balance: int, amount: int) -> None:
        self.account = account
        self.balance = balance
        self.amount = amount
        super().__init__(
            f"overdraft on account {account!r}: balance {format_cents(balance)} "
            f"cannot cover {format_cents(amount)}"
        )


class UnknownAccountError(LedgerError):
    """Raised when an account name does not exist."""

    def __init__(self, name: str) -> None:
        self.name = name
        super().__init__(f"unknown account: {name!r}")


class ValidationError(LedgerError):
    """Raised for bad user input."""


def format_cents(cents: int) -> str:
    """Render integer cents as a signed currency string, e.g. -1234 -> '-12.34'."""
    sign = "-" if cents < 0 else ""
    whole, frac = divmod(abs(int(cents)), 100)
    return f"{sign}{whole}.{frac:02d}"


def parse_amount(text: str) -> int:
    """Parse a decimal amount string ('12', '12.5', '-3.25') into integer cents."""
    if text is None:
        raise ValidationError("amount is required")
    cleaned = str(text).strip().replace(",", "").lstrip("+")
    if cleaned.startswith("$"):
        cleaned = cleaned[1:]
    try:
        from decimal import Decimal, InvalidOperation

        value = Decimal(cleaned)
    except (InvalidOperation, ValueError):
        raise ValidationError(f"not a valid amount: {text!r}") from None
    cents = int((value * 100).to_integral_value())
    return cents


@dataclass(frozen=True)
class Account:
    """An account with a name and a running balance in cents."""

    name: str
    balance: int = 0
    id: int | None = None
    created_at: str = field(default_factory=lambda: datetime.now(timezone.utc).isoformat())

    def __post_init__(self) -> None:
        if not str(self.name).strip():
            raise ValidationError("account name must not be empty")

    def __str__(self) -> str:
        return f"{self.name}: {format_cents(self.balance)}"


@dataclass(frozen=True)
class Txn:
    """A single movement of money between two accounts.

    ``src`` is ``None`` for an external deposit/withdrawal, ``dst`` is ``None``
    for an external withdrawal.  ``amount`` is always positive cents.
    """

    amount: int
    src: str | None = None
    dst: str | None = None
    memo: str = ""
    on: date | None = None
    id: int | None = None

    def __post_init__(self) -> None:
        if int(self.amount) <= 0:
            raise ValidationError("amount must be positive")
        if self.src is None and self.dst is None:
            raise ValidationError("a transaction needs a source or a destination")
        if self.src is not None and self.src == self.dst:
            raise ValidationError("source and destination must differ")

    @property
    def month(self) -> str:
        d = self.on or date.today()
        return f"{d.year:04d}-{d.month:02d}"

    def __str__(self) -> str:
        return f"{self.src or 'external'} -> {self.dst or 'external'} {format_cents(self.amount)}"

"""sqlite3-backed persistence for accounts and transactions."""

from __future__ import annotations

import sqlite3
from datetime import date
from pathlib import Path

from ledger.models import (
    Account,
    OverdraftError,
    Txn,
    UnknownAccountError,
    ValidationError,
)

SCHEMA = """
CREATE TABLE IF NOT EXISTS accounts (
    id          INTEGER PRIMARY KEY AUTOINCREMENT,
    name        TEXT NOT NULL UNIQUE,
    created_at  TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS txns (
    id      INTEGER PRIMARY KEY AUTOINCREMENT,
    src     TEXT,
    dst     TEXT,
    amount  INTEGER NOT NULL CHECK (amount > 0),
    memo    TEXT NOT NULL DEFAULT '',
    day     TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS txns_src ON txns(src);
CREATE INDEX IF NOT EXISTS txns_dst ON txns(dst);
"""


class Store:
    """A ledger store.  Pass ``':memory:'`` for an ephemeral database."""

    def __init__(self, path: str | Path = ":memory:") -> None:
        self.path = str(path)
        if self.path == ":memory:":
            self._conn = sqlite3.connect(":memory:")
        else:
            parent = Path(self.path).parent
            if str(parent) and not parent.exists():
                parent.mkdir(parents=True, exist_ok=True)
            self._conn = sqlite3.connect(self.path)
        self._conn.row_factory = sqlite3.Row
        self._conn.execute("PRAGMA foreign_keys = ON")
        self._conn.executescript(SCHEMA)
        self._conn.commit()

    # ---- lifecycle ---------------------------------------------------
    def close(self) -> None:
        self._conn.close()

    def __enter__(self) -> "Store":
        return self

    def __exit__(self, *exc_info: object) -> None:
        self.close()

    # ---- accounts ----------------------------------------------------
    def add_account(self, name: str, opening: int = 0) -> Account:
        name = str(name).strip()
        if not name:
            raise ValidationError("account name must not be empty")
        try:
            cur = self._conn.execute(
                "INSERT INTO accounts (name, created_at) VALUES (?, datetime('now'))",
                (name,),
            )
        except sqlite3.IntegrityError:
            raise ValidationError(f"account already exists: {name!r}") from None
        if opening:
            self._conn.execute(
                "INSERT INTO txns (src, dst, amount, memo, day) VALUES (NULL, ?, ?, ?, ?)",
                (name, int(opening), "opening balance", date.today().isoformat()),
            )
        self._conn.commit()
        return self.get(name) if opening else Account(
            name=name,
            balance=0,
            id=int(cur.lastrowid),
            created_at=self._created_at(name),
        )

    def _created_at(self, name: str) -> str:
        row = self._conn.execute("SELECT created_at FROM accounts WHERE name = ?", (name,)).fetchone()
        return row["created_at"] if row else ""

    def get(self, name: str) -> Account:
        row = self._conn.execute(
            "SELECT id, name, created_at FROM accounts WHERE name = ?", (name,)
        ).fetchone()
        if row is None:
            raise UnknownAccountError(name)
        return Account(
            name=row["name"],
            balance=self.balance(name),
            id=row["id"],
            created_at=row["created_at"],
        )

    def list_accounts(self) -> list[Account]:
        rows = self._conn.execute("SELECT name FROM accounts ORDER BY name").fetchall()
        return [self.get(r["name"]) for r in rows]

    def _require(self, name: str) -> None:
        row = self._conn.execute("SELECT 1 FROM accounts WHERE name = ?", (name,)).fetchone()
        if row is None:
            raise UnknownAccountError(name)

    # ---- money -------------------------------------------------------
    def balance(self, name: str) -> int:
        """Net balance in cents: deposits into ``name`` minus withdrawals from it."""
        self._require(name)
        row = self._conn.execute(
            "SELECT COALESCE(SUM(CASE WHEN dst = ? THEN amount ELSE 0 END), 0)"
            " - COALESCE(SUM(CASE WHEN src = ? THEN amount ELSE 0 END), 0) AS bal"
            " FROM txns WHERE dst = ? OR src = ?",
            (name, name, name, name),
        ).fetchone()
        return int(row["bal"])

    def add(self, name: str, amount: int, memo: str = "", on: date | None = None) -> Txn:
        """Deposit ``amount`` cents into ``name`` (negative = withdrawal)."""
        self._require(name)
        amount = int(amount)
        if amount == 0:
            raise ValidationError("amount must be non-zero")
        day = (on or date.today()).isoformat()
        if amount > 0:
            txn = Txn(amount=amount, dst=name, memo=memo, on=on)
            src, dst = None, name
        else:
            mag = -amount
            current = self.balance(name)
            if current < mag:
                raise OverdraftError(name, current, mag)
            txn = Txn(amount=mag, src=name, memo=memo, on=on)
            src, dst = name, None
        cur = self._conn.execute(
            "INSERT INTO txns (src, dst, amount, memo, day) VALUES (?, ?, ?, ?, ?)",
            (src, dst, txn.amount, memo, day),
        )
        self._conn.commit()
        return Txn(
            amount=txn.amount, src=src, dst=dst, memo=memo, on=on, id=int(cur.lastrowid)
        )

    def transfer(
        self, src: str, dst: str, amount: int, memo: str = "", on: date | None = None
    ) -> Txn:
        """Move ``amount`` cents from ``src`` to ``dst``; raises OverdraftError if short."""
        amount = int(amount)
        if amount <= 0:
            raise ValidationError("transfer amount must be positive")
        if src == dst:
            raise ValidationError("source and destination must differ")
        self._require(src)
        self._require(dst)
        current = self.balance(src)
        if current < amount:
            raise OverdraftError(src, current, amount)
        day = (on or date.today()).isoformat()
        cur = self._conn.execute(
            "INSERT INTO txns (src, dst, amount, memo, day) VALUES (?, ?, ?, ?, ?)",
            (src, dst, amount, memo, day),
        )
        self._conn.commit()
        return Txn(amount=amount, src=src, dst=dst, memo=memo, on=on, id=int(cur.lastrowid))

    def list_txns(
        self, account: str | None = None, month: str | None = None
    ) -> list[Txn]:
        """Return transactions, newest last, optionally filtered."""
        sql = "SELECT id, src, dst, amount, memo, day FROM txns"
        clauses: list[str] = []
        params: list[object] = []
        if account is not None:
            clauses.append("(src = ? OR dst = ?)")
            params.extend([account, account])
        if month is not None:
            clauses.append("substr(day, 1, 7) = ?")
            params.append(month)
        if clauses:
            sql += " WHERE " + " AND ".join(clauses)
        sql += " ORDER BY id"
        rows = self._conn.execute(sql, params).fetchall()
        return [
            Txn(
                id=r["id"],
                src=r["src"],
                dst=r["dst"],
                amount=r["amount"],
                memo=r["memo"],
                on=date.fromisoformat(r["day"]),
            )
            for r in rows
        ]

    # convenience alias
    def list(self, account: str | None = None, month: str | None = None) -> list[Txn]:
        return self.list_txns(account=account, month=month)

"""Monthly summary reporting."""

from __future__ import annotations

from collections import defaultdict
from dataclasses import dataclass, field

from ledger.models import format_cents
from ledger.store import Store


@dataclass
class AccountSummary:
    name: str
    inflow: int = 0  # cents received this month (deposits + incoming transfers)
    outflow: int = 0  # cents paid out this month
    count: int = 0

    @property
    def net(self) -> int:
        return self.inflow - self.outflow


@dataclass
class MonthlyReport:
    month: str
    accounts: dict[str, AccountSummary] = field(default_factory=dict)
    external_in: int = 0
    external_out: int = 0

    @property
    def total_inflow(self) -> int:
        return sum(a.inflow for a in self.accounts.values())

    @property
    def total_outflow(self) -> int:
        return sum(a.outflow for a in self.accounts.values())

    @property
    def txn_count(self) -> int:
        return sum(a.count for a in self.accounts.values())

    def render(self) -> str:
        lines = [f"Monthly summary for {self.month}", "-" * 40]
        if not self.accounts:
            lines.append("(no activity)")
        for name in sorted(self.accounts):
            s = self.accounts[name]
            lines.append(
                f"{name:<16} in {format_cents(s.inflow):>10}  "
                f"out {format_cents(s.outflow):>10}  net {format_cents(s.net):>10}  "
                f"({s.count} txn{'s' if s.count != 1 else ''})"
            )
        lines.append("-" * 40)
        lines.append(
            f"total in {format_cents(self.total_inflow)}  "
            f"total out {format_cents(self.total_outflow)}  "
            f"external in/out {format_cents(self.external_in)}/{format_cents(self.external_out)}"
        )
        return "\n".join(lines)


def monthly_summary(store: Store, month: str) -> MonthlyReport:
    """Build a report for ``month`` formatted as ``YYYY-MM``."""
    if len(month) != 7 or month[4] != "-":
        raise ValueError(f"month must be YYYY-MM, got {month!r}")
    year, mon = month.split("-")
    if not (year.isdigit() and mon.isdigit() and 1 <= int(mon) <= 12):
        raise ValueError(f"month must be YYYY-MM, got {month!r}")

    report = MonthlyReport(month=month)
    for txn in store.list_txns(month=month):
        if txn.src is None and txn.dst is not None:
            report.external_in += txn.amount
        elif txn.dst is None and txn.src is not None:
            report.external_out += txn.amount
        for side, is_in in ((txn.src, False), (txn.dst, True)):
            if side is None:
                continue
            summary = report.accounts.setdefault(side, AccountSummary(name=side))
            summary.count += 1
            if is_in:
                summary.inflow += txn.amount
            else:
                summary.outflow += txn.amount
    return report


def available_months(store: Store) -> list[str]:
    """Distinct months with activity, ascending."""
    months: dict[str, int] = defaultdict(int)
    for txn in store.list_txns():
        months[txn.month] += 1
    return sorted(months)
